import {
    Table,
    BooleanColumn,
    ChoiceColumn,
    DaysOfWeekColumn,
    GenericColumn,
    GuidColumn,
    IntegerDateColumn,
    ReferenceColumn,
    ScheduleDateTimeColumn,
    StringColumn,
} from '../../db'

/**
 * Schedule Entry - one entry on a `cmn_schedule`, either a single block or the
 * definition of a recurring one. Maintenance windows and blackout/freeze periods are
 * modelled as a `cmn_schedule` plus its entries here; there is no separate calendar
 * table.
 *
 * `repeat_type` drives which of the recurrence columns apply: `monthly_type` for
 * monthly, `yearly_type` for yearly, and `float_day`/`float_week` for the "nth weekday
 * of the month" forms.
 */
export const cmn_schedule_span = Table({
    display: 'name',
    extends: 'business_calendar_span',
    label: 'Schedule Entry',
    name: 'cmn_schedule_span',
    schema: {
        all_day: BooleanColumn({
            default: false,
            label: 'All Day',
        }),
        days_of_week: DaysOfWeekColumn({
            default: '1',
            label: 'Days of week',
        }),
        end_date_time: ScheduleDateTimeColumn({
            label: 'End date time',
        }),
        float_day: ChoiceColumn({
            choices: {
                1: { label: 'Sunday', sequence: 1 },
                2: { label: 'Monday', sequence: 2 },
                3: { label: 'Tuesday', sequence: 3 },
                4: { label: 'Wednesday', sequence: 4 },
                5: { label: 'Thursday', sequence: 5 },
                6: { label: 'Friday', sequence: 6 },
                7: { label: 'Saturday', sequence: 7 },
            },
            default: '1',
            dropdown: 'dropdown_without_none',
            label: 'Float day',
        }),
        float_week: ChoiceColumn({
            choices: {
                1: { label: '1st', sequence: 1 },
                2: { label: '2nd', sequence: 2 },
                3: { label: '3rd', sequence: 3 },
                4: { label: '4th', sequence: 4 },
                last: { label: 'Last', sequence: 5 },
            },
            default: '1',
            dropdown: 'dropdown_without_none',
            label: 'Float week',
        }),
        month: GenericColumn({
            columnType: 'month_of_year',
            label: 'Month',
        }),
        monthly_type: ChoiceColumn({
            choices: {
                dom: { label: 'Day of the month', sequence: 1 },
                nth: { label: 'Day of the Week', sequence: 2 },
                lwdom: { label: 'Last Week Day of the Month', sequence: 3 },
                ldom: { label: 'Last Day of the Month', sequence: 4 },
            },
            default: 'dom',
            dropdown: 'dropdown_without_none',
            label: 'Monthly type',
        }),
        name: StringColumn({
            label: 'Name',
            maxLength: 80,
        }),
        notes: StringColumn({
            label: 'Notes',
            maxLength: 1000,
        }),
        override_start_date: IntegerDateColumn({
            label: 'Override start date',
        }),
        parent: ReferenceColumn({
            label: 'Parent',
            referenceTable: 'cmn_schedule_span',
        }),
        repeat_count: GenericColumn({
            columnType: 'repeat_count',
            default: '1',
            label: 'Repeat count',
        }),
        repeat_type: GenericColumn({
            choices: {
                daily: { label: 'Daily', sequence: 0 },
                weekdays: { label: 'Every Weekday (Mon-Fri)', sequence: 1 },
                weekends: { label: 'Every Weekend (Sat, Sun)', sequence: 2 },
                weekMWF: { label: 'Every Mon, Wed, Fri', sequence: 3 },
                weekTT: { label: 'Every Tue, Thu', sequence: 4 },
                weekly: { label: 'Weekly', sequence: 5 },
                monthly: { label: 'Monthly', sequence: 6 },
                yearly: { label: 'Yearly', sequence: 7 },
                specific: { label: 'Specific', sequence: 8 },
            },
            columnType: 'repeat_type',
            dropdown: 'dropdown_with_none',
            label: 'Repeat type',
        }),
        repeat_until: IntegerDateColumn({
            label: 'Repeat until',
        }),
        schedule: ReferenceColumn({
            label: 'Schedule',
            referenceTable: 'cmn_schedule',
        }),
        show_as: ChoiceColumn({
            choices: {
                busy: { label: 'Busy', sequence: 1 },
                free: { label: 'Free', sequence: 2 },
                tentative: { label: 'Tentative', sequence: 3 },
            },
            default: 'busy',
            dropdown: 'dropdown_without_none',
            label: 'Show as',
        }),
        start_date_time: ScheduleDateTimeColumn({
            label: 'Start date time',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
        type: ChoiceColumn({
            choices: {
                appointment: { label: 'Appointment', sequence: 1 },
                call: { label: 'Phone call', sequence: 2 },
                exclude: { label: 'Excluded', sequence: 3 },
                meeting: { label: 'Meeting', sequence: 4 },
                time_off: { label: 'Time off', sequence: 5 },
            },
            dropdown: 'dropdown_with_none',
            label: 'Type',
        }),
        yearly_type: ChoiceColumn({
            choices: {
                doy: { label: 'Day of the year', sequence: 1 },
                float: { label: 'Floating', sequence: 2 },
            },
            default: 'doy',
            dropdown: 'dropdown_without_none',
            label: 'Yearly type',
        }),
    },
})
